SET lock_timeout = '100ms';
DO $$
DECLARE
  attempt int := 0;
  col_exists boolean;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'region'
  ) INTO col_exists;
  IF col_exists THEN
    RAISE NOTICE 'Column region already exists, skipping';
    RETURN;
  END IF;
  LOOP
    BEGIN
      ALTER TABLE orders ADD COLUMN region text NOT NULL DEFAULT 'EU';
      EXIT;
    EXCEPTION WHEN lock_not_available THEN
      attempt := attempt + 1;
      IF attempt > 60 THEN
        RAISE EXCEPTION 'Failed to acquire lock after 60 attempts';
      END IF;
      PERFORM pg_sleep(0.2);
    END;
  END LOOP;
END $$;
